import { describe, expect, it } from "vitest";
// Generated by tools/tests/test_learn.py (VIEW_CASES) — the same file pytest compares against.
import viewsJson from "../../tools/tests/testdata/trace_views_fixture.json";
import type { CallStackState, GridState, IntervalsState, Trace, TreeState } from "./trace";
import { heapAsTree, intervalBounds, isTrace, layoutTree, packRows, viewId } from "./trace";

const views = viewsJson as unknown as Record<"tree" | "grid" | "heap" | "intervals", Trace>;

describe("views fixture", () => {
  it.each(Object.entries(views))("%s is a valid trace with state for every view", (_, t) => {
    expect(isTrace(t)).toBe(true);
    for (const step of t.steps)
      for (const spec of t.view) expect(step.state[viewId(spec)]).toBeDefined();
  });
});

describe("tree layout", () => {
  const t = views.tree;
  const tree = t.steps[0]!.state.tree as TreeState;

  it("places nodes in-order with depths", () => {
    const placed = layoutTree(tree);
    expect(placed.map((p) => p.val)).toEqual([9, 3, 15, 20, 7]); // in-order
    expect(placed.map((p) => p.depth)).toEqual([1, 0, 2, 1, 2]);
    expect(new Set(placed.map((p) => p.x)).size).toBe(placed.length);
  });

  it("is cycle-safe and handles an empty tree", () => {
    expect(layoutTree({ root: null, nodes: [], pointers: {}, groups: {} })).toEqual([]);
    const loop: TreeState = {
      root: 0,
      nodes: [{ id: 0, val: 1, left: 0, right: null }],
      pointers: {},
      groups: {},
    };
    expect(layoutTree(loop)).toHaveLength(1);
  });

  it("shows the recursion in the call stack", () => {
    const depths = t.steps.map((s) => (s.state.stack as CallStackState).frames.length);
    expect(Math.max(...depths)).toBeGreaterThanOrEqual(4);
    expect((t.steps[0]!.state.stack as CallStackState).frames[0]!.fn).toBe("max_depth");
  });
});

describe("heap, grid, intervals", () => {
  it("maps a heap array to a tree", () => {
    const tree = heapAsTree([1, 3, 2, 7]);
    expect(tree.nodes[0]).toMatchObject({ left: 1, right: 2 });
    expect(tree.nodes[1]).toMatchObject({ left: 3, right: null });
    expect(layoutTree(tree).map((p) => p.val)).toEqual([7, 3, 1, 2]);
    expect(heapAsTree([]).root).toBeNull();
  });

  it("grid fixture fills the LCS table", () => {
    const last = views.grid.steps[views.grid.steps.length - 1]!.state.dp as GridState;
    expect(last.rows[3]).toEqual([0, 1, 2]);
    expect(last.col_labels).toEqual(["a", "c"]);
  });

  it("stacks overlapping intervals into rows", () => {
    expect(
      packRows([
        [1, 3],
        [2, 6],
        [8, 10],
      ]),
    ).toEqual([0, 1, 0]);
    expect(
      packRows([
        [1, 2],
        [3, 4],
      ]),
    ).toEqual([0, 0]);
    expect(
      packRows([
        [1, 5],
        [2, 3],
        [4, 6],
      ]),
    ).toEqual([0, 1, 1]);
  });

  it("intervals share one axis", () => {
    const last = views.intervals.steps[views.intervals.steps.length - 1]!.state
      .iv as IntervalsState;
    expect(intervalBounds(last)).toEqual([1, 10]);
    expect(intervalBounds({ lanes: {}, pointers: {} })).toEqual([0, 1]);
    expect(intervalBounds({ lanes: { a: [[2, 2]] }, pointers: {} })).toEqual([2, 3]);
  });
});
